    //rd+=0.000001*(1.-abs(sign(rd)));
    rd = normalize(rd);
    //rd = rotationMatrix(m) * rd;
    rd = (lookAt(load(G_camLookat_L,caminfo).xyz, ro, RotateY(load(G_camUp_L,caminfo).xyz,ROT_SPEED*timer))*vec4(rd,0.)).rgb;

}

vec2 pos2uv(vec3 pos, sampler2D caminfo, vec2 ires){
    vec3 ro_old = load(POSITION_last,caminfo).xyz;
    float timer = load(G_timer_L,iChannel0).r;
    ro_old = RotateY(ro_old,ROT_SPEED*timer);
    //vec2 m_old = load(VMOUSE_last,caminfo).xy*vec2(1.,-1.);
    vec3 td = pos - ro_old;
    if(length(td)<0.0001)return vec2(-1.);
    //vec3 dir = normalize(td) * (rotationMatrix(m_old));
    //vec3 dir = (vec4(normalize(td),1.)*lookAt(load(G_camLookat_L,caminfo).xyz, ro_old, load(G_camUp_L,caminfo).xyz)).rgb;
    vec3 dir = (vec4(normalize(td),1.)*lookAt(load(G_camLookat_L,caminfo).xyz, ro_old, RotateY(load(G_camUp_L,caminfo).xyz,ROT_SPEED*timer))).rgb;

    //float fov=camera_fov;
    float fov=load(G_fov_L,iChannel0).r;
    float aspect = ires.x / ires.y;
    float screenSize = (1.0 / (tan(((180.-fov)* (3.1415926 / 180.0)) / 2.0)));
    dir.z+=0.0001*(1.-abs(sign(dir.z)));
    return dir.xy * (.5/screenSize) / dir.z ;
}

vec3 rgb2ycocg(in vec3 rgb)
{
return rgb;
    float co = rgb.r - rgb.b;
    float t = rgb.b + co / 2.0;
    float cg = rgb.g - t;
    float y = t + cg / 2.0;
    return vec3(y, co, cg);
}


vec3 ycocg2rgb(in vec3 ycocg)
{
return ycocg;
    float t = ycocg.r - ycocg.b / 2.0;
    float g = ycocg.b + t;
    float b = t - ycocg.g / 2.0;
    float r = ycocg.g + b;
    return vec3(r, g, b);
}

vec3 RGBtoYCoCg(vec3 c)
{
return c;
    //return rgb2ycocg(c);
    return mat3(0.25, 0.5, -0.25, 0.5, 0, 0.5, 0.25, -0.5, -0.25) * c;
}

vec3 YCoCgToRGB(vec3 c)
{
return c;
    //return ycocg2rgb(c);
    return mat3(1, 1, 1, 1, 0, -1, -1, 1, -1) * c;
}

vec4 clipToAABB(in vec4 cOld, in vec4 cNew, in vec4 center, in vec4 halfSize)
{
    vec4 r = cOld - cNew;
    vec4 m = (center + halfSize) - cNew;
    vec4 n = (center - halfSize) - cNew;

    if (r.x > m.x + EPS)
		r *= (m.x / r.x);
	if (r.y > m.y + EPS)
		r *= (m.y / r.y);
	if (r.z > m.z + EPS)
		r *= (m.z / r.z);
    if (r.w > m.w + EPS)
		r.w *= (m.w / r.w);

	if (r.x < n.x - EPS)
		r *= (n.x / r.x);
	if (r.y < n.y - EPS)
		r *= (n.y / r.y);
	if (r.z < n.z - EPS)
		r *= (n.z / r.z);
    if (r.w < n.w - EPS)
		r.w *= (n.w / r.w);

	return cNew + r;
}

vec4 SampleTextureCatmullRom(sampler2D tex, vec2 texSize, vec2 uv)
{
    vec2 samplePos = uv * texSize;
    vec2 texPos1 = floor(samplePos - 0.5) + 0.5;

    vec2 f = samplePos - texPos1;

    vec2 w0 = f * ( -0.5 + f * (1.0 - 0.5*f));
    vec2 w1 = 1.0 + f * f * (-2.5 + 1.5*f);
    vec2 w2 = f * ( 0.5 + f * (2.0 - 1.5*f) );
    vec2 w3 = f * f * (-0.5 + 0.5 * f);

    vec2 w12 = w1 + w2;
    vec2 offset12 = w2 / w12;

    vec2 texPos0 = texPos1 - vec2(1.0);
    vec2 texPos3 = texPos1 + vec2(2.0);
    vec2 texPos12 = texPos1 + offset12;

    texPos0 /= texSize;
    texPos3 /= texSize;
    texPos12 /= texSize;

    vec4 result = vec4(0.0);
    result += textureLod(tex, vec2(texPos0.x,  texPos0.y), 0.) * w0.x * w0.y;
    result += textureLod(tex, vec2(texPos12.x, texPos0.y), 0.) * w12.x * w0.y;
    result += textureLod(tex, vec2(texPos3.x,  texPos0.y), 0.) * w3.x * w0.y;

    result += textureLod(tex, vec2(texPos0.x,  texPos12.y), 0.) * w0.x * w12.y;
    result += textureLod(tex, vec2(texPos12.x, texPos12.y), 0.) * w12.x * w12.y;
    result += textureLod(tex, vec2(texPos3.x,  texPos12.y), 0.) * w3.x * w12.y;

    result += textureLod(tex, vec2(texPos0.x,  texPos3.y), 0.) * w0.x * w3.y;
    result += textureLod(tex, vec2(texPos12.x, texPos3.y), 0.) * w12.x * w3.y;
    result += textureLod(tex, vec2(texPos3.x,  texPos3.y), 0.) * w3.x * w3.y;

    return result;
}

float distancePixel22( vec2 prevFragCoord, vec3 pos, sampler2D samplerx, vec2 ires, vec3 p_ro, vec3 p_rd){
    if(  min(ires.xy-1., prevFragCoord) != prevFragCoord
      || max(vec2(0.)      , prevFragCoord) != prevFragCoord) return MAX_DIST;

    float prev_d = textureLod(samplerx, prevFragCoord/ires.xy,0.).a;
    vec3 prevPos = p_ro + p_rd*prev_d;
    return length(prevPos-pos);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float a = .1;

    ivec2 ipx = ivec2(fragCoord);

    // adding halton_px_shift to fragCoord not needed
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    uv.y *= iResolution.y/iResolution.x;

    vec2 halton_px_shift = load(HALTON,iChannel0).xy;
    float curr_d = textureLod(iChannel1, (fragCoord - halton_px_shift) / iResolution.xy, 0.).w;
    vec4 curr_color = textureLod(iChannel1, (fragCoord - halton_px_shift) / iResolution.xy, 0.);

    vec4 new = vec4(RGBtoYCoCg(curr_color.rgb), curr_color.a);

#ifdef TEMPORAL_REPROJECT

    vec3 ro;
    vec3 rd;
    SetCamera(uv, iChannel0, ro, rd, iResolution.xy);

    vec3 pro;
    vec3 prd;
    SetCamera_prev(uv, iChannel0, pro, prd, iResolution.xy);

    vec3 pos = ro + rd * curr_d;

    // adding prevUv to fragCoord not needed
    vec2 prevUv = pos2uv(pos, iChannel0, iResolution.xy);
    vec2 prevFragCoord = prevUv * iResolution.y + iResolution.xy/2.0;
    vec2 puv = prevFragCoord/iResolution.xy;


    //vec4 hist = texture(iChannel2, puv);
    //vec4 hist = getTextureSmooth(iChannel2, iResolution.xy, puv);
    vec4 hist = SampleTextureCatmullRom(iChannel2, iResolution.xy, puv);

    vec4 old = vec4(RGBtoYCoCg(hist.rgb),hist.a);
#else
    ivec2 sp = ivec2(fragCoord);
    vec4 old = vec4(RGBtoYCoCg(texelFetch(iChannel2, sp, 0).rgb),texelFetch(iChannel2, sp, 0).a);
#endif

#ifdef VARIANCE_CLIPPING
    vec4 avg = new;
    vec4 var = new * new;

    for (int i = 0; i < OFFSET_COUNT; i++)
    {
        vec4 tex_data = texelFetch(iChannel1, ipx + off[i], 0);
        vec4 tex = vec4(RGBtoYCoCg(tex_data.rgb),tex_data.a);

        avg += tex;
        var += tex * tex;
    }
    avg /= float(OFFSET_COUNT + 1);
    var /= float(OFFSET_COUNT + 1);

    vec4 sig = sqrt(max(var - avg * avg, vec4(0)));

    const float g = 1.;
    vec4 cmin = avg - sig * g;
    vec4 cmax = avg + sig * g;

    #if 0
    vec4 clip = clamp(old, cmin, cmax);
    #else
    vec4 clip = clipToAABB(old, clamp(avg, cmin, cmax), avg, sig);
    #endif

    old = mix(old, clip, 1.);
#endif
    bool res_ch = load(RES_CHANGE,iChannel0).x<0.5;
    vec4 col = iFrame != 0 && !res_ch ? mix(old, new, a) : new;
#ifdef ENABLE_TAA
    fragColor = vec4(YCoCgToRGB(col.rgb), curr_d);
#else
    fragColor = vec4(texelFetch(iChannel2, ivec2(fragCoord), 0).rgb, curr_d);
#endif


#ifdef SHOW_DISOCCLUSION

    if (puv.x < 0. || puv.x >= 1. || puv.y < 0. || puv.y >= 1. ||
        distance(pos, (pro+prd*hist.a)) > 2.*0.1*curr_d)
    {
        fragColor = vec4(1, 0, 0, curr_d);
    }
#endif

#ifdef SHOW_MOTION
    fragColor = vec4((fragCoord/iResolution.xy - puv) * 50., 0, curr_d);
#endif
    fragColor.rgb=clamp(fragColor.rgb,0.,100.); // seems color can be little negative
}
#endif

// FSR from
// https://www.shadertoy.com/view/stXSWB


/* EASU stage
*
* This takes a reduced resolution source, and scales it up while preserving detail.
*
* Updates:
*   stretch definition fixed. Thanks nehon for the bug report!
*/

vec3 FsrEasuCF(vec2 p) {
    return texture(iChannel2,p).rgb;
}

/**** EASU ****/
void FsrEasuCon(
    out vec4 con0,
    out vec4 con1,
    out vec4 con2,
    out vec4 con3,
    // This the rendered image resolution being upscaled
    vec2 inputViewportInPixels,
    // This is the resolution of the resource containing the input image (useful for dynamic resolution)
    vec2 inputSizeInPixels,
    // This is the display resolution which the input image gets upscaled to
    vec2 outputSizeInPixels
)
{
    // Output integer position to a pixel position in viewport.
    con0 = vec4(
        inputViewportInPixels.x/outputSizeInPixels.x,
        inputViewportInPixels.y/outputSizeInPixels.y,
        .5*inputViewportInPixels.x/outputSizeInPixels.x-.5,
        .5*inputViewportInPixels.y/outputSizeInPixels.y-.5
    );
    // Viewport pixel position to normalized image space.
    // This is used to get upper-left of 'F' tap.
    con1 = vec4(1,1,1,-1)/inputSizeInPixels.xyxy;
    // Centers of gather4, first offset from upper-left of 'F'.
    //      +---+---+
    //      |   |   |
    //      +--(0)--+
    //      | b | c |
    //  +---F---+---+---+
    //  | e | f | g | h |
    //  +--(1)--+--(2)--+
    //  | i | j | k | l |
    //  +---+---+---+---+
    //      | n | o |
    //      +--(3)--+
    //      |   |   |
    //      +---+---+
    // These are from (0) instead of 'F'.
    con2 = vec4(-1,2,1,2)/inputSizeInPixels.xyxy;
    con3 = vec4(0,4,0,0)/inputSizeInPixels.xyxy;
}

// Filtering for a given tap for the scalar.
void FsrEasuTapF(
    inout vec3 aC, // Accumulated color, with negative lobe.
    inout float aW, // Accumulated weight.
    vec2 off, // Pixel offset from resolve position to tap.
    vec2 dir, // Gradient direction.
    vec2 len, // Length.
    float lob, // Negative lobe strength.
    float clp, // Clipping point.
    vec3 c
)
{
    // Tap color.
    // Rotate offset by direction.
    vec2 v = vec2(dot(off, dir), dot(off,vec2(-dir.y,dir.x)));
    // Anisotropy.
    v *= len;
    // Compute distance^2.
    float d2 = min(dot(v,v),clp);
    // Limit to the window as at corner, 2 taps can easily be outside.
    // Approximation of lancos2 without sin() or rcp(), or sqrt() to get x.
    //  (25/16 * (2/5 * x^2 - 1)^2 - (25/16 - 1)) * (1/4 * x^2 - 1)^2
    //  |_______________________________________|   |_______________|
    //                   base                             window
    // The general form of the 'base' is,
    //  (a*(b*x^2-1)^2-(a-1))
    // Where 'a=1/(2*b-b^2)' and 'b' moves around the negative lobe.
    float wB = .4 * d2 - 1.;
    float wA = lob * d2 -1.;
    wB *= wB;
    wA *= wA;
    wB = 1.5625*wB-.5625;
    float w=  wB * wA;
    // Do weighted average.
    aC += c*w;
    aW += w;
}

//------------------------------------------------------------------------------------------------------------------------------
// Accumulate direction and length.
void FsrEasuSetF(
    inout vec2 dir,
    inout float len,
    float w,
    float lA,float lB,float lC,float lD,float lE
)
{
    // Direction is the '+' diff.
    //    a
    //  b c d
    //    e
    // Then takes magnitude from abs average of both sides of 'c'.
    // Length converts gradient reversal to 0, smoothly to non-reversal at 1, shaped, then adding horz and vert terms.
    float lenX = max(abs(lD - lC), abs(lC - lB));
    float dirX = lD - lB;
    dir.x += dirX * w;
    lenX = clamp(abs(dirX)/lenX,0.,1.);
    lenX *= lenX;
    len += lenX * w;
    // Repeat for the y axis.
    float lenY = max(abs(lE - lC), abs(lC - lA));
    float dirY = lE - lA;
    dir.y += dirY * w;
    lenY = clamp(abs(dirY) / lenY,0.,1.);
    lenY *= lenY;
    len += lenY * w;
}

//------------------------------------------------------------------------------------------------------------------------------
void FsrEasuF(
    out vec3 pix,
    vec2 ip, // Integer pixel position in output.
    // Constants generated by FsrEasuCon().
    vec4 con0, // xy = output to input scale, zw = first pixel offset correction
    vec4 con1,
    vec4 con2,
    vec4 con3
)
{
    //------------------------------------------------------------------------------------------------------------------------------
    // Get position of 'f'.
    vec2 pp = ip * con0.xy + con0.zw; // Corresponding input pixel/subpixel
    vec2 fp = floor(pp);// fp = source nearest pixel
    pp -= fp; // pp = source subpixel

    //------------------------------------------------------------------------------------------------------------------------------
    // 12-tap kernel.
    //    b c
    //  e f g h
    //  i j k l
    //    n o
    // Gather 4 ordering.
    //  a b
    //  r g
    vec2 p0 = fp * con1.xy + con1.zw;

    // These are from p0 to avoid pulling two constants on pre-Navi hardware.
    vec2 p1 = p0 + con2.xy;
    vec2 p2 = p0 + con2.zw;
    vec2 p3 = p0 + con3.xy;

    // TextureGather is not available on WebGL2
    vec4 off = vec4(-.5,.5,-.5,.5)*con1.xxyy;
    // textureGather to texture offsets
    // x=west y=east z=north w=south
    vec3 bC = FsrEasuCF(p0 + off.xw); float bL = bC.g + 0.5 *(bC.r + bC.b);
    vec3 cC = FsrEasuCF(p0 + off.yw); float cL = cC.g + 0.5 *(cC.r + cC.b);
    vec3 iC = FsrEasuCF(p1 + off.xw); float iL = iC.g + 0.5 *(iC.r + iC.b);
    vec3 jC = FsrEasuCF(p1 + off.yw); float jL = jC.g + 0.5 *(jC.r + jC.b);
    vec3 fC = FsrEasuCF(p1 + off.yz); float fL = fC.g + 0.5 *(fC.r + fC.b);
    vec3 eC = FsrEasuCF(p1 + off.xz); float eL = eC.g + 0.5 *(eC.r + eC.b);
    vec3 kC = FsrEasuCF(p2 + off.xw); float kL = kC.g + 0.5 *(kC.r + kC.b);
    vec3 lC = FsrEasuCF(p2 + off.yw); float lL = lC.g + 0.5 *(lC.r + lC.b);
    vec3 hC = FsrEasuCF(p2 + off.yz); float hL = hC.g + 0.5 *(hC.r + hC.b);
    vec3 gC = FsrEasuCF(p2 + off.xz); float gL = gC.g + 0.5 *(gC.r + gC.b);
    vec3 oC = FsrEasuCF(p3 + off.yz); float oL = oC.g + 0.5 *(oC.r + oC.b);
    vec3 nC = FsrEasuCF(p3 + off.xz); float nL = nC.g + 0.5 *(nC.r + nC.b);

    //------------------------------------------------------------------------------------------------------------------------------
    // Simplest multi-channel approximate luma possible (luma times 2, in 2 FMA/MAD).
    // Accumulate for bilinear interpolation.
    vec2 dir = vec2(0);
    float len = 0.;

    FsrEasuSetF(dir, len, (1.-pp.x)*(1.-pp.y), bL, eL, fL, gL, jL);
    FsrEasuSetF(dir, len,    pp.x  *(1.-pp.y), cL, fL, gL, hL, kL);
    FsrEasuSetF(dir, len, (1.-pp.x)*  pp.y  , fL, iL, jL, kL, nL);
    FsrEasuSetF(dir, len,    pp.x  *  pp.y  , gL, jL, kL, lL, oL);

    //------------------------------------------------------------------------------------------------------------------------------
    // Normalize with approximation, and cleanup close to zero.
    vec2 dir2 = dir * dir;
    float dirR = dir2.x + dir2.y;
    bool zro = dirR < (1.0/32768.0);
    dirR = inversesqrt(dirR);
    dirR = zro ? 1.0 : dirR;
    dir.x = zro ? 1.0 : dir.x;
    dir *= vec2(dirR);
    // Transform from {0 to 2} to {0 to 1} range, and shape with square.
    len = len * 0.5;
    len *= len;
    // Stretch kernel {1.0 vert|horz, to sqrt(2.0) on diagonal}.
    float stretch = dot(dir,dir) / (max(abs(dir.x), abs(dir.y)));
    // Anisotropic length after rotation,
    //  x := 1.0 lerp to 'stretch' on edges
    //  y := 1.0 lerp to 2x on edges
    vec2 len2 = vec2(1. +(stretch-1.0)*len, 1. -.5 * len);
    // Based on the amount of 'edge',
    // the window shifts from +/-{sqrt(2.0) to slightly beyond 2.0}.
    float lob = .5 - .29 * len;
    // Set distance^2 clipping point to the end of the adjustable window.
    float clp = 1./lob;

    //------------------------------------------------------------------------------------------------------------------------------
    // Accumulation mixed with min/max of 4 nearest.
    //    b c
    //  e f g h
    //  i j k l
    //    n o
    vec3 min4 = min(min(fC,gC),min(jC,kC));
    vec3 max4 = max(max(fC,gC),max(jC,kC));
    // Accumulation.
    vec3 aC = vec3(0);
    float aW = 0.;
    FsrEasuTapF(aC, aW, vec2( 0,-1)-pp, dir, len2, lob, clp, bC);
    FsrEasuTapF(aC, aW, vec2( 1,-1)-pp, dir, len2, lob, clp, cC);
    FsrEasuTapF(aC, aW, vec2(-1, 1)-pp, dir, len2, lob, clp, iC);
    FsrEasuTapF(aC, aW, vec2( 0, 1)-pp, dir, len2, lob, clp, jC);
    FsrEasuTapF(aC, aW, vec2( 0, 0)-pp, dir, len2, lob, clp, fC);
    FsrEasuTapF(aC, aW, vec2(-1, 0)-pp, dir, len2, lob, clp, eC);
    FsrEasuTapF(aC, aW, vec2( 1, 1)-pp, dir, len2, lob, clp, kC);
    FsrEasuTapF(aC, aW, vec2( 2, 1)-pp, dir, len2, lob, clp, lC);
    FsrEasuTapF(aC, aW, vec2( 2, 0)-pp, dir, len2, lob, clp, hC);
    FsrEasuTapF(aC, aW, vec2( 1, 0)-pp, dir, len2, lob, clp, gC);
    FsrEasuTapF(aC, aW, vec2( 1, 2)-pp, dir, len2, lob, clp, oC);
    FsrEasuTapF(aC, aW, vec2( 0, 2)-pp, dir, len2, lob, clp, nC);
    //------------------------------------------------------------------------------------------------------------------------------
    // Normalize and dering.
    pix=min(max4,max(min4,aC/aW));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 c;
    vec4 con0,con1,con2,con3;

    // "rendersize" refers to size of source image before upscaling.
    vec2 rendersize = iChannelResolution[2].xy;
    FsrEasuCon(
        con0, con1, con2, con3, rendersize, rendersize, iResolution.xy
    );
    FsrEasuF(c, fragCoord, con0, con1, con2, con3);
    fragColor = vec4(c.xyz, 1);
}
